  db_operations: ["messages", "lead_state"],
  state_update: {
    ...($json.state_update || {}),
    stage: "human_handoff",
    human_handoff: true,
    last_bot_action: "pricing_rule_not_found",
    next_goal: "manual_pricing_review"
  },
  notes: [
    ...($json.notes || []),
    "pricing_rule_not_found",
    "handoff_required_after_quote_failure"
